const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs'),path=require('path'),crypto=require('crypto');
(async()=>{const browser=await chromium.launch();const page=await browser.newPage();try{await page.goto('https://chatgpt.com/s/m_6ab691ad087c81919ea2c882178b576d',{waitUntil:'domcontentloaded'});const img=page.getByAltText('Generated image: Dracula-Farm Premium Walnuts').first();await img.waitFor({timeout:25000});const url=await img.getAttribute('src');const response=await page.request.get(url);if(!response.ok()||!response.headers()['content-type'].startsWith('image/'))throw Error('Image download failed');const data=await response.body();const target='outputs/dracula-food/food/assets/produse/dracula-food-nuci-dracula-farm.png';fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,data);console.log(JSON.stringify({target,bytes:data.length,sha256:crypto.createHash('sha256').update(data).digest('hex')}));}finally{await browser.close();}})();
